/* Bizy's Mahjong - offline service worker (generated by build.py; do not edit sw.js, edit src/sw.js).
   - Precaches the app shell (index.html, manifest, icons) into a cache whose name carries a
     hash of the build, so every rebuild produces a new sw.js -> the browser installs it.
   - Cache-first for everything in scope (instant, works offline). The new version is fetched
     in the background when online and used on the next launch/reload (the page reloads by
     itself when an update lands while you are on the setup screen).
   - Only registered when the page is served over http(s); file:// and Capacitor never use it. */
const VERSION = '30951fc3d88e';
const CACHE = 'bizy-mahjong-' + VERSION;
const SHELL = ['./', './index.html', './manifest.webmanifest', './icons/icon-180.png', './icons/icon-192.png', './icons/icon-512.png', './icons/icon.svg'];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE)
    .then(c => c.addAll(SHELL.map(u => new Request(u, { cache: 'reload' }))))   // bypass the HTTP cache
    .then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k.startsWith('bizy-mahjong-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  if (req.mode === 'navigate') {            // any page in scope (incl. ?seed= / ?theme=) -> the app shell
    e.respondWith(caches.open(CACHE).then(c => c.match('./index.html').then(hit => hit || fetch(req))));
    return;
  }
  e.respondWith(caches.open(CACHE).then(c => c.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req).then(res => {
    if (res.ok && res.type === 'basic') c.put(req, res.clone());
    return res;
  }))));
});
